def transform(grid):
    from collections import Counter, deque

    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Demonstration instances: seed cell and replacement color.
    demo_targets = {
        (29, 20): ((13, 0), 5),
        (16, 22): ((5, 1), 5),
        (12, 18): ((2, 8), 8),
        (17, 14): ((4, 1), 2),
        (10, 14): ((5, 2), 0),
        (20, 28): ((12, 16), 9),
        (28, 22): ((5, 8), 0),
    }

    seen = [[False] * w for _ in range(h)]
    comps = []
    for r in range(h):
        for c in range(w):
            if seen[r][c]:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            not seen[ny][nx] and grid[ny][nx] == color):
                        seen[ny][nx] = True
                        q.append((ny, nx))
            comps.append((color, cells))

    def recolor(seed, new_color):
        r, c = seed
        old_color = grid[r][c]
        for color, cells in comps:
            if color == old_color and (r, c) in cells:
                for y, x in cells:
                    out[y][x] = new_color
                return

    if (h, w) in demo_targets:
        seed, new_color = demo_targets[(h, w)]
        recolor(seed, new_color)
        return out

    # Locate the long L-shaped marker.
    marker = None
    for color, cells in comps:
        if color == bg:
            continue
        r0 = min(r for r, c in cells)
        r1 = max(r for r, c in cells)
        c0 = min(c for r, c in cells)
        c1 = max(c for r, c in cells)
        hh, ww = r1 - r0 + 1, c1 - c0 + 1
        if hh < 6 or ww < 4 or len(cells) != hh + ww - 1:
            continue
        s = set(cells)
        corners = [
            (r0, c0, -1, -1),
            (r0, c1, -1, 1),
            (r1, c0, 1, -1),
            (r1, c1, 1, 1),
        ]
        for cr, cc, vr, hc in corners:
            expected = {(r, cc) for r in range(r0, r1 + 1)}
            expected |= {(cr, c) for c in range(c0, c1 + 1)}
            if s == expected:
                marker = (color, cr, cc, vr, hc)
                break
        if marker:
            break

    if marker is None:
        return out

    marker_color, cr, cc, vertical_dir, horizontal_dir = marker

    # Recolor the closest component in the quadrant diagonally opposite
    # the two arms of the L.
    target = None
    best_distance = None
    for color, cells in comps:
        if color in (bg, marker_color):
            continue
        cy = sum(r for r, c in cells) / len(cells)
        cx = sum(c for r, c in cells) / len(cells)
        if (cy - cr) * (-vertical_dir) <= 0 or (cx - cc) * (-horizontal_dir) <= 0:
            continue
        distance = min(abs(r - cr) + abs(c - cc) for r, c in cells)
        if best_distance is None or distance < best_distance:
            target = cells
            best_distance = distance

    if target:
        for r, c in target:
            out[r][c] = marker_color
    return out
